<script setup lang="ts">
import {onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {LocalApiError,operationMessage,type LocalLauncherClient} from './local-api';
import type {ModFileRef,ModLibraryEntry,ModSource,RecordProblem,TaskSnapshot} from './local-types';
const props=defineProps<{client:LocalLauncherClient;revision?:number;installAvailable?:boolean}>();const emit=defineEmits<{submitted:[task:TaskSnapshot];install:[ref:ModFileRef];'open-project':[ref:{source:ModSource;projectId:string}]}>();
const entries=ref<ModLibraryEntry[]>([]),problems=ref<RecordProblem[]>([]),loading=ref(false),busy=ref(''),error=ref(''),notice=ref(''),expired=ref(false);let sequence=0,controller=new AbortController();const lifetime=new AbortController();
function failure(e:unknown){error.value=operationMessage(e);if(e instanceof LocalApiError&&(e.status===401||e.status===403))expired.value=true;}
async function load(){if(expired.value)return;controller.abort();controller=new AbortController();const current=++sequence;loading.value=true;error.value='';try{const listing=await props.client.modLibrary(controller.signal);if(current===sequence){entries.value=listing.entries;problems.value=listing.problems;}}catch(e){if(current===sequence&&!(e instanceof DOMException&&e.name==='AbortError'))failure(e);}finally{if(current===sequence)loading.value=false;}}
async function verify(id:string){if(busy.value||expired.value)return;busy.value=id;error.value='';notice.value='';try{const {task}=await props.client.verifyMod(id,lifetime.signal);notice.value='已提交后台校验，请查看下方任务结果。';emit('submitted',task);}catch(e){failure(e);}finally{busy.value='';}}
async function copy(path:string){try{await navigator.clipboard.writeText(path);notice.value='文件路径已复制。';}catch{notice.value='复制未完成，可选中文件路径手动复制。';}}
onMounted(load);watch(()=>props.revision,load);onBeforeUnmount(()=>{++sequence;controller.abort();lifetime.abort();});
</script>
<template>
 <section class="launcher-mod-library"><div class="launcher-modal-title"><div><span class="launcher-overline">LOCAL MOD LIBRARY</span><h2>收藏你的世界可能</h2></div><button class="launcher-secondary" data-refresh-mod-library :disabled="loading||expired" @click="load">刷新模组库 ↻</button></div><p class="launcher-caption">这里展示有效结构记录。内容可重新校验；下载到库后，尚未装入游戏实例。</p><p v-if="error" class="launcher-inline-notice" role="alert">{{error}}</p><p v-if="notice" class="launcher-inline-notice" role="status">{{notice}}</p><p v-if="loading" class="launcher-caption" role="status">读取本机模组库…</p><section v-if="!loading&&!entries.length" class="launcher-empty launcher-glass"><h2>模组库还是空的</h2><p>从官方源选择兼容文件，下载校验通过后会出现在这里。</p></section><article v-for="entry in entries" :key="entry.id" :data-mod-library-id="entry.id" class="launcher-glass launcher-mod-library-row"><div class="launcher-mod-file-title"><div><span class="launcher-overline">{{entry.source}}</span><h3>{{entry.title||entry.projectId}}</h3><small>{{entry.fileName}} · {{(entry.size/1048576).toFixed(2)}} MiB</small></div><button v-if="installAvailable" class="launcher-secondary" data-install-library-mod :disabled="!!busy||expired" @click="emit('install',{source:entry.source,projectId:entry.projectId,versionId:entry.versionId,fileKey:entry.fileKey})">装入实例…</button><button class="launcher-secondary" data-verify-mod :disabled="!!busy||expired" @click="verify(entry.id)">重新校验</button></div><div class="launcher-tool-tags"><span v-for="version in entry.gameVersions" :key="version">{{version}}</span><span v-for="tag in entry.loaders" :key="tag">{{tag}}</span></div><p class="launcher-mod-digest">SHA-256 · {{entry.sha256}}</p><div class="launcher-mod-path"><code>{{entry.filePath}}</code><button class="launcher-secondary" data-copy-mod-path @click="copy(entry.filePath)">复制路径</button></div><button class="launcher-dependency" @click="emit('open-project',{source:entry.source,projectId:entry.projectId})">查看官方项目与依赖 ↗</button></article><p v-for="problem in problems" :key="problem.recordId" class="launcher-inline-notice">{{problem.recordId}} · {{problem.message}}</p></section>
</template>
